INSERT INTO agent_messages VALUES(42,'39bedc16-48f2-473e-9739-feb51b6f8826','{"id": "msg_68d74b5eea6c8194befb99708028eebd06d3080b035d82e9", "content": [{"annotations": [], "text": "I base my responses on official Ontario healthcare resources, including:\n\n1. **Ontario Ministry of Health** - Provides information about the Ontario Health Insurance Plan (OHIP) including billing codes and service fees.\n2. **Ontario Drug Benefit (ODB) Formulary** - Details about drug coverage, including Limited Use criteria and drug identification numbers (DINs).\n3. **Assistive Devices Program (ADP)** - Guidelines on the availability of funding for various assistive devices and eligibility criteria.\n4. **Official Government Publications and Websites** - For accurate and updated information on healthcare policies and programs.\n\nYou can always verify the information through the official Ontario government healthcare websites.", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-27 02:26:42');
INSERT INTO agent_messages VALUES(43,'1679f700-8e73-4267-b845-b289dfe14372','{"content": "what are your sources", "role": "user"}','2025-09-27 02:27:29');
INSERT INTO agent_messages VALUES(44,'1679f700-8e73-4267-b845-b289dfe14372','{"id": "msg_68d74b92986c8194a17ae8a0ad4d2a2d0de6e523ed15ceff", "content": [{"annotations": [], "text": "My responses are based on official Ontario healthcare resources and guidelines, specifically:\n\n1. **Ontario Ministry of Health**: Provides information regarding the OHIP Schedule of Benefits, including billing codes, fees, and requirements for healthcare services.\n\n2. **Ontario Drug Benefit (ODB) Formulary**: Offers details about drug coverage, Limited Use criteria, and related medications, including their Drug Identification Numbers (DINs).\n\n3. **Assistive Devices Program (ADP)**: Governs coverage and funding for assistive devices, outlining eligibility criteria and application processes.\n\n4. **Ontario Health Insurance Plan (OHIP)**: Covers specifics on physician services, fees, and billing codes.\n\nAll references I use are aligned with the latest available data from these sources to ensure accuracy and compliance with Ontario healthcare regulations.", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-27 02:27:33');
INSERT INTO agent_messages VALUES(45,'test-session-123','{"content": "What is covered under OHIP?", "role": "user"}','2025-09-27 22:18:58');
INSERT INTO agent_messages VALUES(46,'test-session-123','{"id": "msg_68d862d4a9808195ab0045dea81d0ea10f57f8e2c4ac5277", "content": [{"annotations": [], "text": "OHIP (Ontario Health Insurance Plan) covers a range of medically necessary services and procedures for residents of Ontario. Here''s an overview of what''s generally covered:\n\n### 1. **Hospital Services**\n   - **Inpatient and Outpatient Care**: Includes accommodation, nursing care, and other medically necessary services received in a hospital.\n   - **Emergency Room Services**: Treatment for urgent medical conditions.\n\n### 2. **Physician Services**\n   - **Office Visits**: Consultations with family doctors and specialists.\n   - **Surgical Procedures**: A range of surgeries performed by physicians, including minor and major operations.\n   - **Diagnostic Services**: Includes laboratory tests and imaging services (e.g., X-rays, MRIs) ordered by a physician.\n\n### 3. **Medical Procedures**\n   - **Preventive Services**: Routine check-ups, vaccinations, and screenings.\n   - **Chronic Disease Management**: Ongoing assessments and treatments for chronic conditions.\n\n### 4. **Maternity and Child Services**\n   - **Prenatal and Postnatal Care**: Services related to pregnancy, childbirth, and care for newborns.\n\n### 5. **Palliative Care**\n   - Services for patients with terminal illnesses, focusing on comfort and quality of life.\n\n### 6. **Mental Health Services**\n   - Some coverage for psychiatric assessments and services, often provided in hospitals or by community mental health teams.\n\n### 7. **Certain Assistive Devices**\n   - Limited coverage for specific assistive devices when medically necessary. Device funding is often more fully covered under the ADP (Assistive Devices Program).\n\n### 8. **Other Services**\n   - **Allied Health Professionals**: May include limited coverage for physiotherapy, occupational therapy, and other specialized services under certain circumstances.\n\n### **Important Notes**\n- **Eligibility**: Generally available for Ontario residents with valid OHIP cards.\n- **Non-Covered Services**: Services like cosmetic procedures, most dental care, and preventative dental care are often not covered.\n- **Prior Authorization**: Some specialized services may require prior approval from OHIP.\n\nFor specific billing codes, service details, or coverage limitations regarding specific procedures, you may consult the OHIP Schedule of Benefits or your medical billing department. If you have a specific service or procedure in mind, feel free to ask for more detailed information!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-27 22:19:08');
INSERT INTO agent_messages VALUES(47,'test_session','{"content": "Is Tylenol covered by ODB?", "role": "user"}','2025-09-27 23:46:56');
INSERT INTO agent_messages VALUES(48,'test_session','{"id": "msg_68d8777205348194b5500c0e719b317a0889e6e4b6231406", "content": [{"annotations": [], "text": "The specific drug you asked about, **plain Tylenol (acetaminophen)**, is **NOT covered by the Ontario Drug Benefit (ODB)** program.\n\nHowever, related products like **Tylenol with Codeine** may have some covered formulations, depending on specific conditions. If you have questions about those alternatives or require information on other medications, please let me know.", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-27 23:46:59');
