INSERT INTO agent_messages VALUES(52,'12dcd848-1d14-4eda-ac45-0450f613da20','{"id": "msg_68d879af862881938c37cceb3df9abbb0f0c9c70e668a9eb", "content": [{"annotations": [], "text": "Here are the OHIP billing codes for virtual visits:\n\n1. **OHIP Fee Code C990**\n   - **Description**: First person seen\n   - **Fee Amount**: $20.00\n   - **Time Requirement**: Max. 10 (total of first and additional persons seen) per time period\n   - **Medical Specialty**: GP\n   - **Category**: Special Visit Premiums\n\n2. **OHIP Fee Code K990**\n   - **Description**: First person seen\n   - **Fee Amount**: $20.00\n   - **Time Requirement**: Max. 10 (total of first and additional persons seen) per time period\n   - **Medical Specialty**: GP\n   - **Category**: Special Visit Premiums\n\n3. **OHIP Fee Code B988**\n   - **Description**: First person seen\n   - **Fee Amount**: $82.50\n   - **Time Requirement**: No max. per time period\n   - **Medical Specialty**: GP\n   - **Category**: Special Visit Premiums\n   - **Reference**: GP65\n\n4. **OHIP Fee Code H980**\n   - **Description**: First person seen\n   - **Fee Amount**: $20.00\n   - **Time Requirement**: Max. 5 (total of first and additional persons seen) per time period\n   - **Medical Specialty**: GP\n   - **Category**: Special Visit Premiums\n\n5. **OHIP Fee Code B998**\n   - **Description**: First person seen\n   - **Fee Amount**: $82.50\n   - **Time Requirement**: No max. per time period\n   - **Medical Specialty**: GP\n   - **Category**: Special Visit Premiums\n   - **Reference**: GP65\n\n### References\n- For more comprehensive details, refer to the [OHIP Schedule of Benefits (March 2025)](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf). \n\nFeel free to ask if you need further assistance with any specific code or details!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-27 23:56:35');
