INSERT INTO agent_messages VALUES(60,'7425d489-a525-4f9d-973a-afc4e4a7c0fd','{"id": "msg_68d87ee5fff88195873cec143ef63bf00ac39583490f0fcd", "content": [{"annotations": [], "text": "### Eye Assessment OHIP Code Information\n\n1. **Code**: **A115**\n   - **Description**: Major eye examination\n   - **Fee Amount**: $51.10\n   - **Billing Conditions**: Limited to one per patient per consecutive 12-month period.\n   - **Medical Specialty**: Family Practice & Specialty\n   - **Category**: Family Practice & Practice in General (00)\n  \n2. **Code**: **U235**\n   - **Description**: Initial e-assessment\n   - **Fee Amount**: $45.85\n   - **Medical Specialty**: Ophthalmology\n   - **Category**: Ophthalmology (23)\n  \n3. **Code**: **C233**\n   - **Description**: Specific assessment\n   - **Fee Amount**: $57.70\n   - **Medical Specialty**: Ophthalmology\n   - **Category**: Ophthalmology (23)\n\n### References\n- **For More Information**: You can access the full [OHIP Schedule of Benefits](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf) for further details on these codes.\n\n### Next Steps\n- Ensure your documentation aligns with the specific billing conditions outlined for code A115 if you plan to use this code for reimbursement.", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 00:18:50');
