INSERT INTO agent_messages VALUES(64,'4825006a-d9e3-4f39-bce3-5d0e79ed7583','{"id": "msg_68d9defeb3fc8194a23de7f567e2bf89037c3d1990135a30", "content": [{"annotations": [], "text": "For billing a diabetes follow-up under OHIP, you can use the following codes:\n\n1. **K046** - Diabetes Team Management\n   - **Fee**: $115.00\n   - **Limitations**: Limited to one service per patient per 12-month period.\n   - **Specialty**: Endocrinology & Metabolism\n\n2. **K045** - Diabetes Management by a Specialist\n   - **Fee**: $76.20\n   - **Specialty**: Endocrinology & Metabolism\n\n3. **K030** - Diabetic Management Assessment\n   - **Fee**: $40.55\n   - **Specialty**: Vitreous\n\n### Summary of Codes\n- **K046**: Team management, limited to once a year.\n- **K045**: Specialist management.\n- **K030**: Assessment service.\n\n### Important Notes\n- Ensure that the services billed correspond to the specific assessments and management performed.\n- It is also beneficial to reference the [OHIP Schedule of Benefits](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf) for any additional details or changes in billing.\n\nIf you have any further questions or need additional assistance, feel free to ask!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-29 01:21:08');
