INSERT INTO agent_messages VALUES(88,'5d21a110-1d84-430a-a482-60eb15d97045','{"id": "msg_68d9f430197c8193b1e410ceb368a12f035ffe05b97db332", "content": [{"annotations": [], "text": "### Executive Summary\n\nOzempic (semaglutide) is covered by the Ontario Drug Benefit (ODB) program; however, it is specifically listed as an anti-diabetic medication, not for weight loss. Ozempic''s coverage does not include criteria related to weight loss, and it does not have Limited Use (LU) conditions associated with obesity management under the ODB.\n\n### Comprehensive Coverage Analysis\n\n**Coverage Determination:**\n- **Drug Name:** Ozempic (semaglutide)\n- **DIN:** 02540258\n- **Coverage Status:** General Benefit under ODB\n- **Purpose:** Covered as an anti-diabetic agent, specifically classified under incretin mimetics.\n- **Price:** $223.26 per unit.\n- **LU Code:** Not applicable; no Limited Use criteria for weight loss.\n- **Therapeutic Class:** Hormones and Substitutes, Category: Anti-Diabetic Agents.\n\n**Eligibility Criteria:**\n- **Coverage:** Intended for managing type 2 diabetes.\n- **Medical Justification:** Required for diabetes treatment, not approved under ODB for weight loss or obesity management.\n\n**Substitution & Alternative Options:**\n- **Interchangeable Product Options:** None specified for non-diabetic indications.\n\n**Prior Authorization Process:**\n- **No specific prior authorization for weight loss:** ODB does not cover Ozempic for this purpose, so no related submission process is outlined.\n\n### Sources & Tool Contributions\n\n**MCP Tools Used:**\n- **odb_get:** Retrieved coverage status and details for Ozempic under ODB.\n\n**Citations:**\n- Source: [Ontario Drug Benefit Formulary - Ozempic, DIN: 02540258](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02540258)\n\nPlease ensure you are prescribing Ozempic in accordance with ODB''s covered indications to ensure compliance and reimbursement.", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-29 02:51:35');
